DBUS_ROOT_SERVER_ADDRESS = 'org.freedesktop.DBus'
DBUS_ROOT_SERVER_PATH = '/org/freedesktop/DBus'
DBUS_ROOT_SERVER_INTERFACE = 'org.freedesktop.DBus'
AUDIOSOURCE_SERVER_ADDRESS = 'com.syng.AudioSourceServer'
AUDIOSOURCE_SERVER_RUNTIME_PATH = '/com/syng/AudioSource/Runtime'
DBUS_OBJECT_MANAGER_INTERFACE = 'org.freedesktop.DBus.ObjectManager'

DEFAULT_STEM_POSITIONS = {'0':{
            "radius": 0.7,
            "rotation": 0.0,
            "snap_to_cell": "",
            "snapped_rotation": 0.0,
            "surround_width": 120.0,
            "type": "panner_v2",
            "version": "-1",
            "x": 0.0,
            "y": 0.0
          }}

DEFAULT_TONE_CONTROL = { 'tilt': 0., 'bass': 0., 'mapping_version': '1.0.0', 'version': '0' }

DEFAULT_SOURCE_SHADER_MAP = {
    'airplay2': default_stereo_shader,
    'spotify': default_stereo_shader,
    'tidal': default_stereo_shader,
    'file@welcome-to-syng': default_stereo_shader
}

USBHOSTSOURCE_OPTIONS_PATH = "/etc/syng/apps/usbhostsource/options.conf"


class UnknownSourceError(Exception):
    code = 10
    msg = 'Action requested for an unknown source'


async def get_dbus_root_proxy(bus):
    """A quick helper for getting a proxy open to org.freedesktop.DBus."""
    introspection = await bus.introspect(DBUS_ROOT_SERVER_ADDRESS, DBUS_ROOT_SERVER_PATH)
    proxy = bus.get_proxy_object(DBUS_ROOT_SERVER_ADDRESS, DBUS_ROOT_SERVER_PATH, introspection)
    iface = proxy.get_interface(DBUS_ROOT_SERVER_INTERFACE)

    return iface


def check_source_id(self, source_id):
    # use current active source if None specified
    if not source_id:
        # specifying no source for websocket commands doesn't scale to source layering
        # this will return the alphabetically first source if we have multiple sources active!
        # but this is just used for prototyping software (SoundObjects), therefore not an issue
        source_id = next(iter(self.currently_active_sources))

    if not source_id or source_id not in self.source_proxies:
        raise UnknownSourceError()

    return source_id


def transport_method(name):
    """A simple decorator for reducing redundant transport method code."""
    def transport_method_helper(fn):
        @wraps(fn)
        def wrapper(self, source_id=None, **kwargs):
            source_id = check_source_id(self, source_id)

            local_method = getattr(self.source_proxies[source_id], name)
            local_method()

            return fn(self)
        return wrapper
    return transport_method_helper


class ProxyManager:
    """A helper class for maintaining proxies to all known local audio sources."""

    @classmethod
    async def create(cls):
        mqtt_client = await OptimisticMQTTClient.create()
        bus = await MessageBus(bus_type=BusType.SYSTEM).connect()
        root_proxy = await get_dbus_root_proxy(bus)

        audiosource_server_alive = await root_proxy.call_name_has_owner(AUDIOSOURCE_SERVER_ADDRESS)

        if audiosource_server_alive:
            logging.info('AudioSourceServer found; trying to initialize source proxies.')

            # Subscribe to the object manager to keep the source_proxies up to date
            try:
                introspection = await bus.introspect(AUDIOSOURCE_SERVER_ADDRESS, AUDIOSOURCE_SERVER_RUNTIME_PATH)
                proxy = bus.get_proxy_object(AUDIOSOURCE_SERVER_ADDRESS, AUDIOSOURCE_SERVER_RUNTIME_PATH, introspection)
                object_mgr_proxy = proxy.get_interface(DBUS_OBJECT_MANAGER_INTERFACE)
            except Exception as e:
                logging.info('Failed to get a proxy open to the AudioSourceServer, waiting for it to come back online.')
                return ProxyManager(mqtt_client, bus, root_proxy, None)

            pm = ProxyManager(mqtt_client, bus, root_proxy, object_mgr_proxy)

            # Then fetch the initial set of sources
            await pm.update_source_proxies_async()
            return pm

        # If the audio source server is not up, syngsoundserver might be down. So here we construct
        # our proxy manager without a proxy to the object manager and await sss coming back up
        logging.info('AudioSourceServer not found; deferring source proxy initialization.')
        return ProxyManager(mqtt_client, bus, root_proxy, None)

    def __init__(self, mqtt_client, bus, root_proxy, object_mgr_proxy):
        self.mqtt_client = mqtt_client
        self.bus = bus
        self.root_proxy = root_proxy
        self.object_mgr_proxy = object_mgr_proxy
        self.cell_positions = [{'x': 0, 'y': 0, 'z': 0, 'rotation': 0, 'height_layer': 0}]
        self.nearby_walls = [{}]
        self.reference_circle = {
            'x_m': 0,
            'y_m': 0,
            'radius_m': 1.15,
            'rotation_deg': 0,
        }
        self.listener_position = { 'x_m': 0, 'y_m': 0 }

        self.room_id = None
        self.runtime_proxies = dict()
        self.source_proxies = dict()
        self.currently_active_sources = set()
        self.source_shader_map = copy.copy(DEFAULT_SOURCE_SHADER_MAP)
        self.source_channel_layout = dict()
        self.handle_positions = dict()
        self.expected_handle_positions = dict()
        self._debounced_position_update = dict()
        self.tone_control = DEFAULT_TONE_CONTROL
        self.expected_tone_control = dict()
        self._debounced_tone_control_update = None
        self.expected_listener_position = dict()
        self._debounced_listener_position_update = None

        self.override_object_focus = -1.0 # this is used for testing/simulating omni/traditional speaker (poles)

        self.calibration_runner_proxy = syngnative.CalibrationRunnerProxy()
        self.root_proxy.on_name_owner_changed(self.handle_name_owner_change)

        self.bass_distribution_proxy = syngnative.BassDistributionProxy()
        self.snapped_cells = set()

        self.listener_offset_proxy = syngnative.ListenerOffsetProxy()

        if self.object_mgr_proxy:
            self.object_mgr_proxy.on_interfaces_added(self.update_source_proxies)
            self.object_mgr_proxy.on_interfaces_removed(self.update_source_proxies)

        # Here we equip each ProxyManager with a Router to fall back to our newly
        # deprecated message routing. This preserves the existing behavior to avoid
        # breaking changes, but eventually can be likely be removed.
        if bool(os.environ.get('IS_MOCK')):
            from .mock.MockOTAServer import MockOTAServer as ota_server
            from .mock.MockAudioServer import MockAudioServer as audio_server
        else:
            from .core.OTAServer import OTAServer as ota_server
            from .core.AudioSourceServer import AudioSourceServer as audio_server

        self.router = Router(None, bus, ota_server, audio_server)

        self.pd_process_id = -1;

        self.cso = syngnative.CloudStateObserver(lambda s: self.set_cloud_state(s))

    def set_cloud_state(self, state):
        room_cells = [state.cell, *state.neighbors]
        online_cells = [c for c in room_cells if c.is_online]

        new_cell_positions = [{'x': c.position.x, 'y': c.position.y, 'z': c.position.z, 'rotation': c.position.angle, 'height_layer': c.position.height_layer, 'serial_number' : c.serial_number} for c in online_cells]
        if self.cell_positions != new_cell_positions:
            self.cell_positions = new_cell_positions
            logging.info(f'[ProxyManager] New recorded cell positions: {self.cell_positions}')

        new_nearby_walls = [[{'angle_deg': w.angle, 'distance_m': w.distance, 'likelihood': w.likelihood, 'close_to_wall': w.is_close_to_wall} for w in c.nearby_walls] for c in online_cells]
        if self.nearby_walls != new_nearby_walls:
            self.nearby_walls = new_nearby_walls
            logging.info(f'[ProxyManager] New recorded nearby_walls: {self.nearby_walls}')

        room_state = state.room
        if room_state:
            self.set_room_state(room_state)

        self.set_cell_state(state.cell)

    def set_room_state(self, room_state):
        # update reference_circle
        if room_state.reference_circle:
            rc = room_state.reference_circle
            new_reference_circle = {'x_m': rc.x, 'y_m': rc.y, 'radius_m': rc.radius, 'rotation_deg': rc.angle, 'version': room_state.reference_circle_version}
            if self.reference_circle != new_reference_circle:
                self.reference_circle = new_reference_circle
                logging.info(f'[ProxyManager] New recorded reference circle: {self.reference_circle}')

        # update the room-id
        self.room_id = room_state.room_id

        # update listener_position
        if room_state.listener_position:
            received_version = room_state.listener_position_version
            lp = room_state.listener_position
            received_listener_position = {'x_m': lp.x, 'y_m': lp.y, 'version': received_version}

            expected_version = self.expected_listener_position.get('version', None)

            if expected_version:
                if expected_version == received_version:
                    logging.debug(f'[ProxyManager] set_room_state, listener_position. Received expected version {received_version}, doing nothing.')
                    self.listener_position = received_listener_position
                else:
                    logging.info(f'[ProxyManager] set_room_state, listener_position. Expected: {expected_version}, Received: {received_version}')
            else:
                # if we're not expecting anything just set it
                self.listener_position = received_listener_position
                try:
                    self.room_set_listener_position(listener_position=self.listener_position, skip_persist=True)
                except Exception as e:
                    logging.error(f'[ProxyManager] Failed to set listener_position, skipping: {e}')

        # update tone control
        if room_state.tone_control:
            received_version = room_state.tone_control_version
            tc = room_state.tone_control
            received_settings = {'bass': tc.bass, 'tilt': tc.tilt, 'version': received_version, 'mapping_version': tc.mapping_version}
            expected_version = self.expected_tone_control.get('version', None)

            if expected_version:
                if expected_version == received_version:
                    logging.debug(f'[ProxyManager] set_room_state, tone control. Received expected version {received_version}, doing nothing.')
                    self.tone_control = received_settings
                else:
                    logging.info(f'[ProxyManager] set_room_state, tone control. Expected: {expected_version}, Received: {received_version}')
            else:
                # if we're not expecting anything just set it
                self.tone_control = received_settings
                try:
                    self.room_set_tone_control(handles=self.tone_control, skip_persist=True)
                except Exception as e:
                    logging.error(f'[ProxyManager] Failed to set tone control, skipping: {e}')

        # update the sources about height processing
        have_height_cells = True if get_number_of_height_layers(self.cell_positions) > 1 else False
        # set height cell processing for all sources
        try:
            for sp in self.source_proxies:
                self.source_proxies[sp].enable_height_processing(have_height_cells)
        except Exception as e:
            logging.error(f"error setting enable_height_processing: {e}'")


    def set_cell_state(self, state):
        # Populate the map from source_id to shader
        self.source_shader_map = copy.copy(DEFAULT_SOURCE_SHADER_MAP)

        # add all snapped cells to this set while going through all sources
        self.snapped_cells.clear()

        self.currently_active_sources.clear()

        for source in state.audio_sources:
            source_id = source.id

            if source.active:
                self.currently_active_sources.add(source_id)

            # we need this in source_set_stem_positions for a fallback option
            self.source_channel_layout[source_id] = source.channel_layout

            # Here, if we get a persisted shader_name, we use that to update the source_shader_map
            # Else, we fall back to the channel_layout-based mapping
            shader_name = source.shader_name
            if shader_name and hasattr(shaders, shader_name):
                self.source_shader_map[source_id] = getattr(shaders, shader_name)
            else:
                shader_fct = self.find_default_shader(source_id, source.channel_layout)
                if shader_fct:
                    self.source_shader_map[source_id] = shader_fct

            # Here we update the handle_positions map with the newly received data, if it matches
            # what we're expecting
            received_positions = source.positions
            received_version = received_positions.get('0', {}).get('version', None)

            try:
                if source_id in self.expected_handle_positions:
                    expected_version = self.expected_handle_positions[source_id].get('0', {}).get('version', -1)

                    if received_version == expected_version:
                        logging.debug(f'[ProxyManager] set_cell_state, stem positions. Received expected version {received_version}, doing nothing.')
                        self.handle_positions[source_id] = received_positions
                    else:
                        logging.info(f'[ProxyManager] set_cell_state, stem positions. Expected: {expected_version}, Received: {received_version}')
                else:
                    # And if we're not expecting anything, just write what we get
                    self.handle_positions[source_id] = received_positions
                    self.source_set_stem_positions(source_id=source_id, handles=self.handle_positions[source_id], skip_persist=True)
            except UnknownSourceError as e:
                logging.debug(f'[ProxyManager] No proxy ready for {source_id} for persisted source position')
            except jsonrpc.ServerError as e:
                logging.error(f'[ProxyManager] Failed to assign persisted stem positions, skipping: {e}')

            # check whether the source is snapped to a cell
            snapped_cell = received_positions['0'].get('snap_to_cell', 'None')
            if snapped_cell != 'None' and snapped_cell:
                self.snapped_cells.add(received_positions['0']['snap_to_cell'])

        # set the snapped cells to get excluded from bass distribution
        try:
            self.bass_distribution_proxy.set_disabled_cells(json.dumps(list(self.snapped_cells)))
        except Exception as e:
            logging.warn(f'Failed to set bass dist: {e}')


    def find_default_shader(self, source_id, channel_layout):
        stem_positions_exclude_list = ['CalibrationClient', 'RefAudioSource', 'PdAudioSource', 'file@ready-to-setup', 'file@multi-cell-orientation', 'file@connection-success']
        if source_id in stem_positions_exclude_list:
            # don't assign a shader for excluded sources
            return None

        if 'hdmi@' in source_id:
            # hdmi always has the 6 channel surround graph loaded, therefore use the appropriate shader
            return variable_51_shader

        num_channels = len(channel_layout.split())

        if channel_layout == "C":
            return default_mono_shader
        elif channel_layout == "L R":
            return default_stereo_shader
        elif channel_layout == "L R C Lfe Ls Rs":
            return variable_51_shader
        elif channel_layout == "L R C Lfe Ls Rs Tsl Tsr":
            return variable_51_2_shader
        elif channel_layout == "L R C Lfe Ls Rs Tfl Tfr Trl Trr":
            return variable_51_4_shader
        elif channel_layout == "L R C Lfe Lss Rss Lrs Rrs":
            return variable_71_shader
        elif channel_layout == "L R C Lfe Lss Rss Lrs Rrs Tsl Tsr":
            return variable_71_2_shader
        elif channel_layout == "L R C Lfe Lss Rss Tfl Tfr Trl Trr Lrs Rrs":
            return variable_71_4_shader
        elif num_channels == 12:
            return variable_71_4_shader
        elif num_channels == 13:
            return ring_8_4_1_shader
        elif num_channels == 14:
            return variable_91_4_shader

    def find_default_stem_positions(self):
        num_cells = len(self.cell_positions)

        stem_positions = copy.deepcopy(DEFAULT_STEM_POSITIONS)

        if num_cells == 1:
            stem_positions['0']['snapped_rotation'] = 180
        # TODO: this should cover more use-cases!

        return stem_positions

    def set_default_stem_positions(self):
        # iterate over all available sources and set a default stem position to the cloud so the app knows about it

        for source_id in self.source_proxies:
            self.handle_positions[source_id] = self.find_default_stem_positions()
            self.source_set_stem_positions(source_id=source_id, handles=self.handle_positions[source_id], skip_persist=False)

    def handle_name_owner_change(self, name, previous_owner, new_owner):
        if len(previous_owner) == 0 and len(new_owner) > 0:
            return self.handle_name_acquired(name)
        if len(previous_owner) > 0 and len(new_owner) == 0:
            return self.handle_name_lost(name)

    def handle_name_acquired(self, name):
        if name == AUDIOSOURCE_SERVER_ADDRESS:
            logging.info('Looks like the AudioSourceServer has come online again, re-establishing proxies')
            t = asyncio.get_running_loop().create_task(self.establish_object_mgr_proxy())
            t.add_done_callback(self.log_future_result)

    async def establish_object_mgr_proxy(self):
        introspection = await self.bus.introspect(AUDIOSOURCE_SERVER_ADDRESS, AUDIOSOURCE_SERVER_RUNTIME_PATH)
        proxy = self.bus.get_proxy_object(AUDIOSOURCE_SERVER_ADDRESS, AUDIOSOURCE_SERVER_RUNTIME_PATH, introspection)

        self.object_mgr_proxy = proxy.get_interface(DBUS_OBJECT_MANAGER_INTERFACE)
        self.object_mgr_proxy.on_interfaces_added(self.update_source_proxies)
        self.object_mgr_proxy.on_interfaces_removed(self.update_source_proxies)

        await self.update_source_proxies_async()

    def handle_name_lost(self, name):
        if name == AUDIOSOURCE_SERVER_ADDRESS:
            logging.info('Looks like the AudioSourceServer has gone down, tearing down proxies.')

            self.object_mgr_proxy = None

            for d in [self.runtime_proxies, self.source_proxies]:
                d.clear()

    def update_source_proxies(self, path = None, properties = None):
        t = asyncio.get_running_loop().create_task(self.update_source_proxies_async(path, properties))
        t.add_done_callback(self.log_future_result)

    def log_future_result(self, fut):
        """A quick helper for logging the completion of an async future."""
        try:
            r = fut.result()

            if r is not None:
                logging.info(f'[Future Result]: Unexpected {r}')
        except Exception as e:
            logging.error(f'[Future Exception]: {e}')

    async def update_source_proxies_async(self, path = None, properties = None):
        for d in [self.runtime_proxies, self.source_proxies]:
            d.clear()

        known_sources = await self.object_mgr_proxy.call_get_managed_objects()

        for s in known_sources.keys():
            try:
                rtp = syngnative.AudioSourceRuntimeProxy(AUDIOSOURCE_SERVER_ADDRESS, s)
                sp = syngnative.AudioSourceProxy(rtp.get_source_destination(), rtp.get_source_path())
                source_id = sp.get_source_id()

                self.source_proxies[source_id] = sp
                self.runtime_proxies[source_id] = rtp

                # As soon as we have a proxy established we checked whether we have an 'old' position for it
                # this speeds up setting spatialization on format changes eg. for HDMI (between stereo and 5.1)
                if source_id in self.handle_positions:
                    try:
                        self.source_set_stem_positions(source_id=source_id, handles=self.handle_positions[source_id], skip_persist=True)
                    except:
                        pass
                # If we don't yet have a position stored, force default object positions to it
                # with our current understanding of the cells and reference circle
                elif source_id in DEFAULT_SOURCE_SHADER_MAP:
                    shader_fn = DEFAULT_SOURCE_SHADER_MAP[source_id]

                    try:
                        self.handle_positions[source_id] = self.find_default_stem_positions()
                        object_positions = shader_fn(self.handle_positions[source_id], self.reference_circle, self.cell_positions, self.nearby_walls, self.listener_position)
                        rtp.set_object_positions(json.dumps(object_positions))
                    except:
                        pass

            except Exception as e:
                logging.info(f'[AudioSource] Failed to get proxies open to {s}, maybe it has already disappeared?')
                continue


    def persist_listener_position(self, listener_position):
        if self._debounced_listener_position_update and not self._debounced_listener_position_update.done():
            self._debounced_listener_position_update.cancel()

        # Once we start the write, make sure we assign the expected settings
        # before yielding to the event loop
        self.expected_listener_position = listener_position

        async def _wrapped_write(client, listener_position):
            # Debounce interval of 300ms
            await asyncio.sleep(0.300)

            try:
                await client.publish(f"cell/{syngnative.get_serial_number()}/listener_position", json.dumps({
                    'id': str(uuid.uuid4()),
                    'timestamp': datetime.datetime.utcnow().isoformat(),
                    'type': 'LISTENER_POSITION_UPDATE',
                    'details': {
                        'version': listener_position["version"],
                        "x_m" : listener_position["x_m"],
                        "y_m" : listener_position["y_m"]
                    }
                }))
            except asyncio.CancelledError:
                # this happens when new data is coming from ui and the task is cancelled during client.publish
                self.expected_listener_position = dict()
                return

            logging.info(f'[MQTT] Listener position update sent (v{listener_position["version"]}).')

            await asyncio.sleep(3.0)

            last_received_listener_position = self.listener_position
            received_version = last_received_listener_position.get('version', '0')
            expected_version = self.expected_listener_position.get('version', '-1')

            self.expected_listener_position = dict()

            if received_version == expected_version:
                logging.info(f'[MQTT] Listener position confirmed.')

        self._debounced_listener_position_update = asyncio.create_task(_wrapped_write(self.mqtt_client, listener_position))


    def persist_tone_control(self, handles):
        if self._debounced_tone_control_update and not self._debounced_tone_control_update.done():
            self._debounced_tone_control_update.cancel()

        # Once we start the write, make sure we assign the expected settings
        # before yielding to the event loop
        self.expected_tone_control = handles

        async def _wrapped_write(client, handles):
            # Debounce interval of 300ms
            await asyncio.sleep(0.300)

            try:
                await client.publish(f"cell/{syngnative.get_serial_number()}/tone_control", json.dumps({
                    'id': str(uuid.uuid4()),
                    'timestamp': datetime.datetime.utcnow().isoformat(),
                    'type': 'TONE_CONTROL_UPDATE',
                    'details': {
                        'version': handles["version"],
                        'mapping_version': handles["mapping_version"],
                        'bass': handles["bass"],
                        'tilt': handles["tilt"],
                    }
                }))
            except asyncio.CancelledError:
                # this happens when new data is coming from ui and the task is cancelled during client.publish
                self.expected_tone_control = dict()
                return

            logging.info(f'[MQTT] Tone control update sent (v{handles["version"]}).')

            await asyncio.sleep(3.0)

            last_received_tone_control = self.tone_control
            received_version = last_received_tone_control.get('version', '0')
            expected_version = self.expected_tone_control.get('version', '-1')

            self.expected_tone_control = dict()

            if received_version == expected_version:
                logging.info(f'[MQTT] Tone control confirmed.')

        self._debounced_tone_control_update = asyncio.create_task(_wrapped_write(self.mqtt_client, handles))


    def persist_source_handle_positions(self, source_id, handle_positions, shader_name=None):
        if (source_id in self._debounced_position_update and
                self._debounced_position_update[source_id] and
                not self._debounced_position_update[source_id].done()):
            self._debounced_position_update[source_id].cancel()

        # Once we start the write, make sure we assign the expected position
        # before yielding to the event loop
        self.expected_handle_positions[source_id] = handle_positions

        async def _wrapped_write(client, source_id, handle_positions):
            # Debounce interval of 300ms
            await asyncio.sleep(0.300)

            try:
                await client.publish(f"cell/{syngnative.get_serial_number()}/sources", json.dumps({
                    'id': str(uuid.uuid4()),
                    'timestamp': datetime.datetime.utcnow().isoformat(),
                    'type': 'STEM_POSITION_UPDATE',
                    'details': {
                        'source_id': source_id,
                        'position': handle_positions,
                        'shader_name': shader_name,
                    }
                }))
            except asyncio.CancelledError:
                # this happens when new data is coming from ui and the task is cancelled during client.publish
                self.expected_handle_positions.pop(source_id)
                return

            logging.info(f'[MQTT] Position update sent (v{handle_positions["0"]["version"]}) for {source_id}, awaiting confirmation.')

            # If, afer 3s, we don't see the expected position confirmed for
            # this source, we want to fallback to the last confirmed position
            # and notify the app. (For now we removed this fallback, revisit this once we have multi-user)
            await asyncio.sleep(3.0)

            # Once we support more than one handle per source, we will want to improve this
            # version comparison to consult those other handles
            last_received_positions = self.handle_positions.get(source_id, DEFAULT_STEM_POSITIONS)
            received_version = last_received_positions.get('0', {}).get('version', 0)
            expected_version = self.expected_handle_positions.get(source_id, {}).get('0', {}).get('version', -1)

            # After making our check we don't need to uphold this expectation
            self.expected_handle_positions.pop(source_id)

            if received_version == expected_version:
                logging.info(f'[MQTT] Position confirmed.')

        def _wrapped_done(f):
            try:
                res = f.result()

                if res:
                    logging.info(f'[MQTT] Position update task result: {res}')
            except asyncio.CancelledError:
                pass
            except Exception as e:
                logging.error(f'[MQTT] Position update task error: {e}')

        self._debounced_position_update[source_id] = asyncio.create_task(_wrapped_write(self.mqtt_client, source_id, handle_positions))
        self._debounced_position_update[source_id].add_done_callback(_wrapped_done)

    async def dispatch(self, req):
        method = req['method']
        params = req['params']

        if hasattr(self, method):
            local_method = getattr(self, method)
            return local_method(**params)

        # If we haven't found a method on the ProxyManager to invoke for the incoming
        # method dispatch, forward it onto the router to preserve existing behavior.
        logging.info(f'[Request Dispatch] Falling back to deprecated router.')
        return await self.router.call(req)

    ## Runtime Methods
    ##################
    def source_activate(self, source_id=None):
        source_id = check_source_id(self, source_id)

        self.runtime_proxies[source_id].activate()
        self.currently_active_sources.add(source_id)
        return "Ok"

    def source_deactivate(self, source_id=None):
        source_id = check_source_id(self, source_id)

        self.runtime_proxies[source_id].deactivate()
        self.currently_active_sources.discard(source_id)
        return "Ok"

    def source_set_stem_positions(self, source_id=None, handles=None, **kwargs):
        source_id = check_source_id(self, source_id)

        if not handles or '0' not in handles or 'version' not in handles['0']:
            if kwargs.get('skip_persist', False):
                logging.info(f'Invalid handle state, but it looks like its from the cloud...')
            else:
                raise jsonrpc.InvalidParamsError(f"Invalid handles: {handles}")

        # By default we try to look up the shader assigned to the source in our map
        shader_fn = self.source_shader_map.get(source_id, None)
        shader_name = None

        # If a shader name is specified in the kwargs, we allow an override
        if 'shader' in kwargs:
            shader_name = kwargs['shader']
            if shader_name and hasattr(shaders, shader_name):
                logging.info(f"Setting shader override to shaders. {shader_name}")
                shader_fn = getattr(shaders, shader_name)
            else:
                # if the shader is not available (eg. None), we reset to the default shader.
                # should we also apply the default shader if there is no shader attribute in the payload?
                channel_layout = self.source_channel_layout.get(source_id, "L R")
                shader_fn = self.find_default_shader(source_id, channel_layout)
                logging.info(f'Shader {shader_name} not available, applying default shader: {shader_fn}.')

        # Don't run a shader if we don't have one assigned.
        if not shader_fn:
            return "Ok"

        reference_circle = {**self.reference_circle, **kwargs.get('reference_circle', {})}

        try:
            object_positions = shader_fn(handles, reference_circle, self.cell_positions, self.nearby_walls, self.listener_position)

            # special handling for listener_position to avoid multiple sources setting different listener positions
            # this doesn't scale if multiple sources want to change the listener position to something custom!
            # in practise this doesn't currently happen
            if 'listener_position' in object_positions:
                if source_id not in self.currently_active_sources:
                    # strip the listener position if source is not active - it does not have authority to set it
                    object_positions.pop('listener_position')
                elif len(self.currently_active_sources) > 1:
                    # strip the listener position if multiple sources are active and it's 'just' the unmodified position
                    if object_positions['listener_position'] == self.listener_position:
                        object_positions.pop('listener_position')

            # for testing, replace focus if desired (poles)
            # this is used to simulate playback via traditional cardioid or omni speakers
            if self.override_object_focus >= 0.0:
                for key in object_positions['objects'].keys():
                    object_positions['objects'][key]['position']['focus'] = self.override_object_focus

            if not kwargs.get('skip_setting_object_positions', False):
                self.runtime_proxies[source_id].set_object_positions(json.dumps(object_positions))
        except Exception as e:
            logging.error(f"Failed to apply source object positions: {e}'")
            raise jsonrpc.ServerError(f'Failed to apply source object positions: {e}')

        if not kwargs.get('skip_persist', False):
            self.persist_source_handle_positions(source_id, handles, shader_name)

        # update bass distribution in case we are snapped to a cell, apply immediately
        # if we unsnap, let the cloud state handle enabling it again (another source might be snapped to the same cell)
        # this will have a little delay, but this is ok...
        snapped_cell = handles['0'].get('snap_to_cell', 'None')
        if snapped_cell != 'None' and snapped_cell:
            self.snapped_cells.add(handles['0']['snap_to_cell'])
            self.bass_distribution_proxy.set_disabled_cells(json.dumps(list(self.snapped_cells)))

        # For debugging allow to return calculated object positions
        return object_positions if kwargs.get('debug_objects', False) else "Ok"

    # used for testing/dev
    def source_get_stem_positions(self, source_id=None):
        if not source_id or source_id not in self.runtime_proxies:
            raise UnknownSourceError()

        handle_positions = self.handle_positions[source_id]
        if source_id in self.expected_handle_positions:
            handle_positions = self.expected_handle_positions[source_id]

        return handle_positions

    # used for testing/dev
    def source_set_object_positions(self, source_id=None, object_positions=None):
        source_id = check_source_id(self, source_id)

        self.runtime_proxies[source_id].set_object_positions(json.dumps(object_positions))
        return "Ok"

    # used for testing/dev
    def source_get_object_positions(self, source_id=None):
        # we have to run the spatialization shader with the last known info to get the objects positions!
        handle_positions = self.source_get_stem_positions(source_id=source_id)
        return self.source_set_stem_positions(source_id=source_id, handles=handle_positions, skip_persist=True, debug_objects=True, skip_setting_object_positions=True)

