    def room_set_tone_control(self, handles, **kwargs):
        if (not 'mapping_version' in handles or
            not 'bass' in handles or
            not 'tilt' in handles or
            not 'version' in handles):
            raise jsonrpc.InvalidParamsError(f"room_set_tone_control, incomplete set of handles {handles}")

        if handles['mapping_version'] != '1.0.0':
            raise jsonrpc.InvalidParamsError(f"Invalid tone control mapping_version: {handles['mapping_version']}")

        # set tone control for all sources
        try:
            for sp in self.source_proxies:
                self.source_proxies[sp].set_tone_control(json.dumps(handles))
        except Exception as e:
            logging.error(f"room_set_tone_control, error applying tone control: {e}'")
            raise jsonrpc.InvalidParamsError(f"room_set_tone_control, error applying tone control {e}")

        if not kwargs.get('skip_persist', False):
            self.persist_tone_control(handles)

        return "Ok"


    def room_set_listener_position(self, listener_position, **kwargs):
        if (not 'x_m' in listener_position or
            not 'y_m' in listener_position or
            not 'version' in listener_position):
            raise jsonrpc.InvalidParamsError(f"room_set_listener_position, incomplete set of parameters {listener_position}")

        try:
            self.listener_offset_proxy.set_position(json.dumps(listener_position))
        except Exception as e:
            logging.error(f"room_set_listener_position, error applying listener position: {e}'")
            raise jsonrpc.InvalidParamsError(f"room_set_listener_position, error applying listener position {e}")

        if not kwargs.get('skip_persist', False):
            self.persist_listener_position(listener_position)

        return "Ok"


    def dev_only_room_set_reference_circle(self, reference_circle=None):
        # this is used for testing/development only - allows room mapping without app, using webapi/Max prototype instead

        if self.room_id and reference_circle and 'x_m' in reference_circle and 'y_m' in reference_circle and 'radius_m' in reference_circle and 'rotation_deg' in reference_circle:

            t = asyncio.get_running_loop().create_task(cloudapi.put_room_state(
            {
                "reference_circle" : {
                    "x_m" : reference_circle["x_m"],
                    "y_m" : reference_circle["y_m"],
                    "radius_m" : reference_circle["radius_m"],
                    "rotation_deg" : reference_circle["rotation_deg"]
                },
                "room_id" : self.room_id
            }))
            t.add_done_callback(self.log_future_result)

            return "Ok"

        raise jsonrpc.InvalidParamsError()


