    def _apply_height_layer_local(self, height_layer):
        """Apply a height-layer change to THIS cell's renderer now, without waiting for the cloud.
        Troubadour fix for docs/SYNG-AIRPLAY-FIXES.md #3: stock cell_set_height_layer only publishes over
        MQTT, so an offline room never applies it. We update our own cell_positions entry, re-derive
        height processing and recompute object positions with the same calls set_room_state/set_cell_state
        use. The MQTT publish still runs, so the cloud stays in sync when reachable."""
        try:
            my = syngnative.get_serial_number()
        except Exception:
            my = None
        try:
            hl = float(height_layer)
        except Exception:
            return
        matched = [c for c in self.cell_positions if c.get('serial_number') == my]
        if not matched and len(self.cell_positions) == 1:
            matched = self.cell_positions          # the lone default entry is us
        if not matched:
            logging.info('[ProxyManager] local height apply: own cell not in cell_positions yet; MQTT only')
            return
        changed = False
        for c in matched:
            if c.get('height_layer') != hl:
                c['height_layer'] = hl; changed = True
        if not changed:
            return
        logging.info(f'[ProxyManager] local height_layer apply: {my} -> {hl}')
        have_height_cells = True if get_number_of_height_layers(self.cell_positions) > 1 else False
        try:
            for sp in self.source_proxies:
                self.source_proxies[sp].enable_height_processing(have_height_cells)
        except Exception as e:
            logging.error(f"[ProxyManager] local height apply, enable_height_processing: {e}")
        for source_id in list(self.source_proxies):
            handles = self.handle_positions.get(source_id)
            if not handles:
                continue
            try:
                self.source_set_stem_positions(source_id=source_id, handles=handles, skip_persist=True)
            except Exception as e:
                logging.info(f"[ProxyManager] local height apply, recompute {source_id}: {e}")

    def cell_set_height_layer(self, height_layer):
        # Troubadour: apply locally first so it works offline, then publish to the cloud as stock does.
        try:
            self._apply_height_layer_local(height_layer)
        except Exception as e:
            logging.error(f"[ProxyManager] _apply_height_layer_local failed, continuing to MQTT: {e}")

        async def _wrapped_write(client, height_layer):

            try:
                await client.publish(f"cell/{syngnative.get_serial_number()}/height_layer", json.dumps({
                    'id': str(uuid.uuid4()),
                    'timestamp': datetime.datetime.utcnow().isoformat(),
                    'type': 'HEIGHT_LAYER_UPDATE',
                    'details': {
                        'height_layer': height_layer
                    }
                }))
            except asyncio.CancelledError:
                return

            logging.info(f'[MQTT] cell height_layer update sent, new height_layer: {height_layer}.')

        asyncio.create_task(_wrapped_write(self.mqtt_client, height_layer))


    def cell_set_usbhostsource_num_channels(self, num_channels):
        if num_channels < 1 or num_channels > 16:
            msg = f"cell_set_usbhostsource_num_channels, invalid num_channels: {num_channels}"
            logging.error(msg)
            raise jsonrpc.InvalidParamsError(msg)
            return

        # update num_routed_channels in options.conf

        with open(USBHOSTSOURCE_OPTIONS_PATH, "r") as options_file:
            options = json.load(options_file)

        options["num_routed_channels"] = num_channels

        with open(USBHOSTSOURCE_OPTIONS_PATH, "w") as options_file:
            json.dump(options, options_file, sort_keys=True, indent=4)

        logging.info(f'Set usbhostsource to support {num_channels} channels, restarting usbhostsource...')

        # brute force restart usbhostsource to apply settings
        os.system("systemctl restart usbhostsource")

        return "Ok"

    def cell_set_usbhostsource_output_support(self, enabled):
        # update output_support in options.conf

        with open(USBHOSTSOURCE_OPTIONS_PATH, "r") as options_file:
            options = json.load(options_file)

        options["output_support"] = True if enabled == True else False

        with open(USBHOSTSOURCE_OPTIONS_PATH, "w") as options_file:
            json.dump(options, options_file, sort_keys=True, indent=4)

        logging.info(f'Set usbhostsource output_support: "{options["output_support"]}", restarting usbhostsource...')

        # brute force restart usbhostsource to apply settings
        os.system("systemctl restart usbhostsource")

        return "Ok"

    def cell_set_usbhostsource_input_channel_map(self, input_channel_map):
        # update input_channel_map in options.conf

        if not isinstance(input_channel_map, list) or not all(type(n) == int for n in input_channel_map):
            msg = f"cell_set_usbhostsource_input_channel_map, invalid input_channel_map: {input_channel_map}"
            logging.error(msg)
            raise jsonrpc.InvalidParamsError(msg)
            return

        with open(USBHOSTSOURCE_OPTIONS_PATH, "r") as options_file:
            options = json.load(options_file)

        options["input_channel_map"] = input_channel_map

        with open(USBHOSTSOURCE_OPTIONS_PATH, "w") as options_file:
            json.dump(options, options_file, sort_keys=True, indent=4)

        logging.info(f'Set usbhostsource input_channel_map: "{options["input_channel_map"]}", restarting usbhostsource...')

        # brute force restart usbhostsource to apply settings
        os.system("systemctl restart usbhostsource")

        return "Ok"

    def cell_set_usbgadgetsource_num_channels(self, num_channels):
        if num_channels < 1 or num_channels > 16:
            msg = f"cell_set_usbgadgetsource_num_channels, invalid num_channels: {num_channels}"
            logging.error(msg)
            raise jsonrpc.InvalidParamsError(msg)
            return

        # stop related services before applying config changes
        os.system("systemctl stop usbgadgetsource")
        os.system("systemctl stop cell-gadget-port0")
        os.system("systemctl stop cell-gadget-port1")

        # generate new channel mask (hex)
        c_chmask = hex((1 << num_channels) - 1)
        # update scheme file: /etc/syng/cell-gadget.scheme
        new_c_chmask_line = f'c_chmask = {c_chmask};'

        for line in fileinput.input("/etc/syng/cell-gadget.scheme", inplace=True):
            print(re.sub('c_chmask *= *0x(\w*) *;', new_c_chmask_line, line), end ='')

        logging.info(f'Set usbgadgetsource to support {num_channels} channels, restarting usb gadget and usbgadgetsource...')

        # restart services to apply settings
        os.system("systemctl start cell-gadget-port0")
        os.system("systemctl start cell-gadget-port1")
        os.system("systemctl start usbgadgetsource")

        return "Ok"

